// ═══════════════════════════════════════════════════════════════
// Lookup helper: linear search in range table
// ═══════════════════════════════════════════════════════════════
template<typename TRange>
static inline CHAOS_IL2CPP_INT32 LookupRange(const TRange* ranges, CHAOS_IL2CPP_INT32 count, CHAOS_IL2CPP_UINT16 cp) noexcept {
    for (CHAOS_IL2CPP_INT32 i = 0; i < count; i++) {
        if (cp >= ranges[i].start && cp <= ranges[i].end) {
            return static_cast<CHAOS_IL2CPP_INT32>(ranges[i].value);
        }
    }
    return -1;  // not found
}

// ═══════════════════════════════════════════════════════════════
// Lookup helper: binary search in linear table
// ═══════════════════════════════════════════════════════════════
template<typename TEntry, typename TVal>
static inline CHAOS_IL2CPP_INT32 LookupEntry(const TEntry* table, CHAOS_IL2CPP_INT32 count, CHAOS_IL2CPP_UINT16 cp, TVal& out_val) noexcept {
    // Linear search for now (tables are small, ~500 entries)
    for (CHAOS_IL2CPP_INT32 i = 0; i < count; i++) {
        if (table[i].codepoint == cp) {
            out_val = table[i].value;
            return 1;
        }
    }
    return 0;
}

